package com.mfrp.plens.controller;
import com.mfrp.plens.dto.*;import com.mfrp.plens.model.ProjectSubmission;import com.mfrp.plens.service.ProjectSubmissionService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/submissions") public class ProjectSubmissionController {private final ProjectSubmissionService service;public ProjectSubmissionController(ProjectSubmissionService service){this.service=service;}@GetMapping public List<ProjectSubmission> all(){return service.findAll();}@PostMapping @ResponseStatus(HttpStatus.CREATED) public ProjectSubmission create(@Valid @RequestBody ProjectSubmissionRequest request){return service.create(request);}@PatchMapping("/{id}/decision") public ProjectSubmission decide(@PathVariable Long id,@Valid @RequestBody DecisionRequest request){return service.decide(id,request.status());}}
